class Ledger:
    def __init__(self, db):
        self.db = db

    def balance(self, account):
        if not isinstance(account, str) or not account:
            raise ValueError('account must be a non‑empty string')
        row = self.db.execute('SELECT cents FROM balances WHERE account=?', (account,)).fetchone()
        return row[0] if row else 0

    def post(self, event_id, account, cents):
        # ---- Parameter validation ------------------------------------------------
        if not isinstance(event_id, str) or not event_id:
            raise ValueError('event_id must be a non‑empty string')
        if not isinstance(account, str) or not account:
            raise ValueError('account must be a non‑empty string')
        # Explicitly reject bools (bool is subclass of int)
        if type(cents) is not int:
            raise ValueError('cents must be an integer (bool not allowed)')
        if cents <= 0:
            raise ValueError('cents must be a positive integer')

        # ---- Atomic operation ----------------------------------------------------
        cur = self.db.cursor()
        try:
            # Check for existing event_id to enforce idempotency
            cur.execute('SELECT account, cents FROM ledger WHERE event_id=?', (event_id,))
            existing = cur.fetchone()
            if existing:
                existing_account, existing_cents = existing
                if existing_account != account or existing_cents != cents:
                    raise ValueError('conflicting payload for existing event_id')
                # Idempotent replay: return current balance without mutating state
                self.db.commit()
                return self.balance(account)

            # Insert new ledger entry and update balance atomically
            cur.execute(
                'INSERT INTO ledger (event_id, account, cents) VALUES (?,?,?)',
                (event_id, account, cents)
            )
            cur.execute(
                'INSERT INTO balances (account, cents) VALUES (?,?) '
                'ON CONFLICT(account) DO UPDATE SET cents=cents+excluded.cents',
                (account, cents)
            )
            self.db.commit()
            return self.balance(account)
        except Exception:
            # Roll back any partial changes to keep state consistent
            self.db.rollback()
            raise

